-- Workshop invoices, credit notes and payments, posted to the ledger (T-72). Tables generated by
-- prisma migrate diff, then reviewed; checks, indexes and triggers are hand-written.

-- AlterEnum
-- This migration adds more than one value to an enum.
-- With PostgreSQL versions 11 and earlier, this is not possible
-- in a single migration. This can be worked around by creating
-- multiple migrations, each migration adding only one value to
-- the enum.


ALTER TYPE "accounting"."JournalSource" ADD VALUE 'invoice';
ALTER TYPE "accounting"."JournalSource" ADD VALUE 'payment';

-- AlterTable
ALTER TABLE "workshop"."job_card" ADD COLUMN     "unpaid_release_at" TIMESTAMPTZ(6),
ADD COLUMN     "unpaid_release_by" UUID,
ADD COLUMN     "unpaid_release_reason" TEXT;

-- CreateTable
CREATE TABLE "accounting"."posting_settings" (
    "company_id" UUID NOT NULL,
    "labour_revenue_account_id" UUID,
    "receivable_account_id" UUID,
    "cash_account_id" UUID,
    "card_account_id" UUID,
    "bank_account_id" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,

    CONSTRAINT "posting_settings_pkey" PRIMARY KEY ("company_id")
);

-- CreateTable
CREATE TABLE "workshop"."invoice" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "job_id" UUID NOT NULL,
    "quote_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "number" TEXT NOT NULL,
    "invoice_date" DATE NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "customer_id" UUID NOT NULL,
    "customer_name" TEXT NOT NULL,
    "subtotal" DECIMAL(14,2) NOT NULL,
    "discount_amount" DECIMAL(14,2) NOT NULL,
    "net_amount" DECIMAL(14,2) NOT NULL,
    "tax_amount" DECIMAL(14,2) NOT NULL,
    "total" DECIMAL(14,2) NOT NULL,
    "tax_code" TEXT,
    "tax_pct" DECIMAL(7,4),
    "prices_include_tax" BOOLEAN NOT NULL,
    "journal_id" UUID NOT NULL,
    "credited" BOOLEAN NOT NULL DEFAULT false,
    "credit_of_id" UUID,
    "reason" TEXT,
    "created_by" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "invoice_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "workshop"."invoice_line" (
    "invoice_id" UUID NOT NULL,
    "line_no" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    "hours" DECIMAL(5,2) NOT NULL,
    "rate" DECIMAL(12,2) NOT NULL,
    "amount" DECIMAL(14,2) NOT NULL,

    CONSTRAINT "invoice_line_pkey" PRIMARY KEY ("invoice_id","line_no")
);

-- CreateTable
CREATE TABLE "workshop"."payment" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "invoice_id" UUID NOT NULL,
    "number" TEXT NOT NULL,
    "method" TEXT NOT NULL,
    "amount" DECIMAL(14,2) NOT NULL,
    "reference" TEXT,
    "idempotency_key" TEXT NOT NULL,
    "journal_id" UUID NOT NULL,
    "received_by" UUID NOT NULL,
    "received_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "payment_pkey" PRIMARY KEY ("id")
);

