CREATE UNIQUE INDEX "payment_company_id_idempotency_key_key" ON "workshop"."payment"("company_id", "idempotency_key");

-- AddForeignKey
ALTER TABLE "workshop"."invoice" ADD CONSTRAINT "invoice_company_id_job_id_fkey" FOREIGN KEY ("company_id", "job_id") REFERENCES "workshop"."job_card"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."invoice" ADD CONSTRAINT "invoice_quote_id_fkey" FOREIGN KEY ("quote_id") REFERENCES "workshop"."quote"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."invoice" ADD CONSTRAINT "invoice_credit_of_id_fkey" FOREIGN KEY ("credit_of_id") REFERENCES "workshop"."invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."invoice_line" ADD CONSTRAINT "invoice_line_invoice_id_fkey" FOREIGN KEY ("invoice_id") REFERENCES "workshop"."invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."payment" ADD CONSTRAINT "payment_invoice_id_fkey" FOREIGN KEY ("invoice_id") REFERENCES "workshop"."invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE workshop.job_card
  ADD CONSTRAINT job_unpaid_release_complete CHECK (
    (unpaid_release_by IS NULL) = (unpaid_release_at IS NULL)
    AND (unpaid_release_by IS NULL) = (unpaid_release_reason IS NULL));

ALTER TABLE workshop.invoice
  ADD CONSTRAINT invoice_kind_valid CHECK (kind IN ('invoice', 'credit_note')),
  ADD CONSTRAINT invoice_credit_shape CHECK (
    (kind = 'invoice' AND credit_of_id IS NULL AND reason IS NULL)
    OR (kind = 'credit_note' AND credit_of_id IS NOT NULL AND reason IS NOT NULL AND NOT credited)),
  ADD CONSTRAINT invoice_amounts CHECK (
    subtotal >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND total > 0
    AND net_amount = subtotal - discount_amount
    AND total = CASE WHEN prices_include_tax THEN net_amount ELSE net_amount + tax_amount END);

-- One live invoice per job (a credited invoice no longer counts).
CREATE UNIQUE INDEX invoice_one_live_per_job ON workshop.invoice (job_id) WHERE kind = 'invoice' AND NOT credited;

ALTER TABLE workshop.invoice_line
  ADD CONSTRAINT invoice_line_values CHECK (hours > 0 AND rate > 0 AND amount >= 0);

ALTER TABLE workshop.payment
  ADD CONSTRAINT payment_method_valid CHECK (method IN ('cash', 'card', 'bank')),
  ADD CONSTRAINT payment_amount_positive CHECK (amount > 0),
  ADD CONSTRAINT payment_reference CHECK (method = 'cash' OR reference IS NOT NULL);

-- Posted documents never change: an invoice only records that a credit note cancelled it.
CREATE OR REPLACE FUNCTION workshop.guard_invoice() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'invoice_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.kind <> 'invoice' OR OLD.credited OR NOT NEW.credited
     OR (to_jsonb(NEW) - 'credited') IS DISTINCT FROM (to_jsonb(OLD) - 'credited') THEN
    RAISE EXCEPTION 'invoice_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER invoice_guard BEFORE UPDATE OR DELETE ON workshop.invoice
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_invoice();
CREATE TRIGGER invoice_line_immutable BEFORE UPDATE OR DELETE ON workshop.invoice_line
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON workshop.payment
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();

-- A credit note cancels a live, unpaid invoice of the same job, for the same total.
CREATE OR REPLACE FUNCTION workshop.guard_credit_note() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  inv workshop.invoice%ROWTYPE;
BEGIN
  IF NEW.kind <> 'credit_note' THEN RETURN NEW; END IF;
  SELECT * INTO inv FROM workshop.invoice WHERE id = NEW.credit_of_id FOR UPDATE;
  IF inv.id IS NULL OR inv.kind <> 'invoice' OR inv.credited OR inv.job_id <> NEW.job_id OR inv.total <> NEW.total THEN
    RAISE EXCEPTION 'credit_note_invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM workshop.payment p WHERE p.invoice_id = inv.id) THEN
    RAISE EXCEPTION 'credit_note_paid_invoice' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER invoice_credit_note BEFORE INSERT ON workshop.invoice
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_credit_note();

-- Payments go to live invoices and never exceed what is owed (the invoice row is locked).
CREATE OR REPLACE FUNCTION workshop.guard_payment() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  inv workshop.invoice%ROWTYPE;
  paid numeric;
BEGIN
  SELECT * INTO inv FROM workshop.invoice WHERE id = NEW.invoice_id FOR UPDATE;
  IF inv.id IS NULL OR inv.kind <> 'invoice' OR inv.credited OR inv.company_id <> NEW.company_id THEN
    RAISE EXCEPTION 'payment_invoice_invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(sum(amount), 0) INTO paid FROM workshop.payment WHERE invoice_id = inv.id;
  IF paid + NEW.amount > inv.total THEN
    RAISE EXCEPTION 'payment_exceeds_balance' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER payment_guard BEFORE INSERT ON workshop.payment
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_payment();

-- Delivery: the invoice is paid in full, or the owner released the car unpaid (T-72).
CREATE OR REPLACE FUNCTION workshop.guard_delivery_paid() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  owed numeric;
BEGIN
  IF NEW.status = 'delivered' AND OLD.status <> 'delivered' AND NEW.unpaid_release_by IS NULL THEN
    SELECT i.total - COALESCE((SELECT sum(p.amount) FROM workshop.payment p WHERE p.invoice_id = i.id), 0)
      INTO owed
      FROM workshop.invoice i
     WHERE i.job_id = NEW.id AND i.kind = 'invoice' AND NOT i.credited;
    IF owed IS NULL OR owed > 0 THEN
      RAISE EXCEPTION 'job_delivery_unpaid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_card_delivery_paid BEFORE UPDATE OF status ON workshop.job_card
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_delivery_paid();

-- Timeline and permissions.
ALTER TABLE workshop.job_event DROP CONSTRAINT job_event_kind_valid;
ALTER TABLE workshop.job_event ADD CONSTRAINT job_event_kind_valid CHECK (kind IN (
  'created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated',
  'inspection', 'photo_added', 'photo_removed',
  'addition_proposed', 'addition_approved', 'addition_declined', 'addition_withdrawn', 'bay',
  'quote_issued', 'quote_approved', 'quote_declined',
  'invoice_posted', 'credit_note_posted', 'payment_received', 'unpaid_release'));

UPDATE iam.role
   SET permissions = (
         SELECT array_agg(DISTINCT p ORDER BY p)
           FROM unnest(permissions || ARRAY['billing.invoice.manage']) AS p),
       version = version + 1,
       updated_at = now()
 WHERE is_system AND code = 'company-admin';
